    required this.channelId,
    required this.joined,
    required this.muted,
    required this.status,
  });

  @override
  int get hashCode =>
      userId.hashCode ^
      channelId.hashCode ^
      joined.hashCode ^
      muted.hashCode ^
      status.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VoiceEntry &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          channelId == other.channelId &&
          joined == other.joined &&
          muted == other.muted &&
          status == other.status;
}

/// One sender's live output levels, for the roster's speaking glow.
/// `voice` and `share` are peaks (0..1) of the DECODED streams — the
/// listener's own volume does not change them.
class VoiceLevel {
  final int userId;
  final double voice;
  final double share;

  const VoiceLevel({
    required this.userId,
    required this.voice,
    required this.share,
  });

  @override
  int get hashCode => userId.hashCode ^ voice.hashCode ^ share.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VoiceLevel &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          voice == other.voice &&
          share == other.share;
}
